mapper.select:
SELECT GET_GLOBAL_NAME(T.TRAIN_DIFF_CODE, #{lang, jdbcType=VARCHAR}) AS TRAIN_DIFF_NAME, GET_GLOBAL_NAME(T.TRAIN_TYPE_CODE, #{lang, jdbcType=VARCHAR}) AS TRAIN_TYPE_NAME, GET_GLOBAL_NAME(T.TRAIN_FORM_CODE, #{lang, jdbcType=VARCHAR}) AS TRAIN_FORM_NAME, T.COURSE_NAME_CODE, T.COUNTS, T.NUMB, T.ALL_TIME, T.TOTAL_PT, ROUND(T.ALL_TIME / NULLIF(T.NUMB, 0), 2) AS AVG_TIME, T.ALL_COST, T.DIRECT_COST, T.INDIRECT_COST, ROUND(T.ALL_COST / NULLIF(T.NUMB, 0), 2) AS AVG_COST FROM (SELECT P.TRAIN_DIFF_CODE, P.TRAIN_TYPE_CODE, P.COURSE_NAME_CODE, P.TRAIN_FORM_CODE, COUNT(P.PLAN_NO) AS COUNTS, SUM() AS NUMB, SUM() AS ALL_TIME, SUM() * SUM() AS TOTAL_PT,
FROM EDU_PLAN_MANAGER P JOIN EDU_BASIC_INFORMATION B ON B.PLAN_NO = P.PLAN_NO AND B.CPNY_ID = P.CPNY_ID JOIN EDU_COST_MANAGER C ON C.BASIC_NO = B.BASIC_NO WHERE P.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND P.TRAIN_DIFF_CODE = #{trainDiffCode, jdbcType=VARCHAR}
AND P.TRAIN_TYPE_CODE = #{trainTypeCode, jdbcType=VARCHAR}
AND UPPER(P.COURSE_NAME_CODE) LIKE '%' || UPPER(#{courseName, jdbcType=VARCHAR}) || '%'
GROUP BY P.TRAIN_DIFF_CODE, P.TRAIN_TYPE_CODE, P.COURSE_NAME_CODE, P.TRAIN_FORM_CODE) T ORDER BY T.TRAIN_DIFF_CODE, T.TRAIN_TYPE_CODE, T.COURSE_NAME_CODE

SELECT T.PERIOD_KEY AS GROUP_NAME, GET_GLOBAL_NAME(T.TRAIN_FORM_CODE, #{lang, jdbcType=VARCHAR}) AS TRAIN_FORM_NAME,
FROM (SELECT TO_CHAR(B.IMPLE_START_DATE, 'YYYY') AS PERIOD_KEY, P.TRAIN_FORM_CODE,
FROM EDU_BASIC_INFORMATION B JOIN EDU_COST_MANAGER C ON C.BASIC_NO = B.BASIC_NO JOIN EDU_PLAN_MANAGER P ON P.PLAN_NO = B.PLAN_NO WHERE B.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND TO_CHAR(B.IMPLE_START_DATE, 'YYYY') = #{year, jdbcType=VARCHAR}
GROUP BY TO_CHAR(B.IMPLE_START_DATE, 'YYYY'), P.TRAIN_FORM_CODE) T ORDER BY T.PERIOD_KEY, TRAIN_FORM_NAME

SELECT SUBSTR(T.PERIOD_KEY, 5, 2) || '/' || SUBSTR(T.PERIOD_KEY, 1, 4) AS GROUP_NAME, GET_GLOBAL_NAME(T.TRAIN_FORM_CODE, #{lang, jdbcType=VARCHAR}) AS TRAIN_FORM_NAME,
FROM (SELECT TO_CHAR(B.IMPLE_START_DATE, 'YYYYMM') AS PERIOD_KEY, P.TRAIN_FORM_CODE,
FROM EDU_BASIC_INFORMATION B JOIN EDU_COST_MANAGER C ON C.BASIC_NO = B.BASIC_NO JOIN EDU_PLAN_MANAGER P ON P.PLAN_NO = B.PLAN_NO WHERE B.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND TO_CHAR(B.IMPLE_START_DATE, 'MMYYYY') = #{month, jdbcType=VARCHAR}
GROUP BY TO_CHAR(B.IMPLE_START_DATE, 'YYYYMM'), P.TRAIN_FORM_CODE) T ORDER BY T.PERIOD_KEY, TRAIN_FORM_NAME

SELECT GET_GLOBAL_NAME(T.TRAIN_FORM_CODE, #{lang, jdbcType=VARCHAR}) AS GROUP_NAME,
FROM (SELECT P.TRAIN_FORM_CODE,
FROM EDU_BASIC_INFORMATION B JOIN EDU_PLAN_MANAGER P ON P.PLAN_NO = B.PLAN_NO AND P.CPNY_ID = B.CPNY_ID JOIN EDU_COST_MANAGER C ON C.BASIC_NO = B.BASIC_NO WHERE B.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND P.TRAIN_FORM_CODE = #{trainFormCode, jdbcType=VARCHAR}
GROUP BY P.TRAIN_FORM_CODE) T ORDER BY GROUP_NAME
